const payload = $json.body ?? $json;
const event = payload.bot_event ?? payload.event;
if (event !== 'transcription.processed' || payload.transcript_status !== 'Success') return [];
if (!payload.bot_id) throw new Error('MeetStream webhook did not include bot_id.');
return [{ json: { ...payload, bot_id: String(payload.bot_id) } }];

const runs = Array.isArray($json.transcriptions) ? $json.transcriptions : [];
const completed = runs
  .filter((run) => run.status === 'Success' && run.transcript_id)
  .sort((a, b) => String(b.created_at ?? '').localeCompare(String(a.created_at ?? '')));
if (!completed.length) throw new Error('No successful post-call transcription run was returned.');
return [{ json: { transcript_id: completed[0].transcript_id } }];

const segments = Array.isArray($json.data) ? $json.data : [];
if (!segments.length) throw new Error('MeetStream returned an empty transcript.');
const fullTranscript = segments
  .map((segment) => `${segment.speaker ?? 'Speaker'}: ${segment.transcript ?? ''}`)
  .join('\n');
const limit = 60000;
const transcript = fullTranscript.length > limit
  ? `${fullTranscript.slice(0, limit)}\n\n[Transcript truncated to ${limit} characters for the summary.]`
  : fullTranscript;
return [{ json: {
  bot_id: $('Accept successful transcript event').item.json.bot_id,
  transcript,
  transcript_truncated: fullTranscript.length > limit
} }];
